{
  "name": "HP 6624A四路可编程直流电源",
  "name_en": "HP 6624A Four-Output Programmable DC Power Supply",
  "manufacturer": "Hewlett-Packard",
  "description": "HP 6624A 是一台四路可编程直流电源，可独立设置各输出通道的电压和电流，并测量实际输出电压与电流。它常用于实验室为电子电路、器件样品和多路测试系统提供稳定直流供电与偏置。",
  "description_en": "The HP 6624A is a four-output programmable DC power supply that can independently set voltage and current for each output channel and measure the actual output voltage and current. It is commonly used in laboratories to provide stable DC power and biasing for electronic circuits, device samples, and multi-rail test setups.",
  "tag_hints": [
    "programmable DC power supply",
    "multi-output power supply",
    "four-channel power supply",
    "voltage and current sourcing",
    "remote voltage sensing",
    "bench electronics testing"
  ],
  "actions": [
    {
      "action_name": "auto-channel_count",
      "description": "获取/设置可用输出通道数量",
      "description_en": "Get/set the number of available output channels"
    },
    {
      "action_name": "auto-clear",
      "description": "将电源恢复到上电初始状态",
      "description_en": "Return the power supply to its power-on initial state"
    },
    {
      "action_name": "auto-current",
      "description": "获取/设置所有通道的输出电流",
      "description_en": "Get/set the output current for all channels"
    },
    {
      "action_name": "auto-voltage",
      "description": "获取/设置所有通道的输出电压",
      "description_en": "Get/set the output voltage for all channels"
    },
    {
      "action_name": "auto-channel",
      "description": "获取指定输出通道",
      "description_en": "Get a specific output channel"
    },
    {
      "action_name": "auto-voltage_sense",
      "description": "获取所有通道的实际检测电压",
      "description_en": "Get the actual sensed voltage for all channels"
    },
    {
      "action_name": "auto-current_sense",
      "description": "获取所有通道的实际测量电流",
      "description_en": "Get the actual measured current for all channels"
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向设备发送原始指令",
      "description_en": "Send a raw command to the device"
    },
    {
      "action_name": "auto-query",
      "description": "发送查询指令并读取设备响应",
      "description_en": "Send a query command and read the device response"
    },
    {
      "action_name": "auto-mode",
      "description": "获取/设置设备工作模式",
      "description_en": "Get/set the device operating mode"
    },
    {
      "action_name": "auto-reset",
      "description": "复位设备",
      "description_en": "Reset the device"
    }
  ]
}

